CREATE TABLE IF NOT EXISTS "organization" (id text PRIMARY KEY,name text NOT NULL,slug text NOT NULL UNIQUE,logo text,"createdAt" timestamptz NOT NULL DEFAULT now(),metadata text);
CREATE TABLE IF NOT EXISTS "member" (id text PRIMARY KEY,"organizationId" text NOT NULL REFERENCES "organization"(id),"userId" text NOT NULL,role text NOT NULL DEFAULT 'viewer',"createdAt" timestamptz NOT NULL DEFAULT now(),UNIQUE("organizationId","userId"));
CREATE TABLE IF NOT EXISTS engagements (id text PRIMARY KEY,organisation_id text NOT NULL REFERENCES "organization"(id),title text NOT NULL,status text NOT NULL DEFAULT 'onboarding',stage text NOT NULL DEFAULT 'Find',data jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,organisation_id));
CREATE TABLE IF NOT EXISTS records (id text PRIMARY KEY,organisation_id text NOT NULL REFERENCES "organization"(id),engagement_id text,kind text NOT NULL CHECK(kind IN ('onboarding','opportunity','remediation','approval','deployment','deliverable','verification','proposal','support','update')),title text NOT NULL,status text NOT NULL,version integer NOT NULL DEFAULT 1 CHECK(version>0),data jsonb NOT NULL DEFAULT '{}',created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(engagement_id,organisation_id) REFERENCES engagements(id,organisation_id),UNIQUE(id,organisation_id));
CREATE INDEX IF NOT EXISTS records_tenant ON records(organisation_id,engagement_id,kind);
CREATE TABLE IF NOT EXISTS record_revisions (record_id text NOT NULL REFERENCES records(id),version integer NOT NULL,data jsonb NOT NULL,actor_id text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(record_id,version));
CREATE TABLE IF NOT EXISTS audit_events (id text PRIMARY KEY,organisation_id text REFERENCES "organization"(id),actor_id text NOT NULL,action text NOT NULL,entity_id text,detail jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS audit_tenant ON audit_events(organisation_id,created_at DESC);
CREATE TABLE IF NOT EXISTS settings (key text PRIMARY KEY,value jsonb NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS aws_connections (id text PRIMARY KEY,organisation_id text NOT NULL REFERENCES "organization"(id),engagement_id text,external_id text NOT NULL UNIQUE,role_arn text,account_id text,status text NOT NULL DEFAULT 'instructions',last_error text,last_checked_at timestamptz,last_synced_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(engagement_id,organisation_id) REFERENCES engagements(id,organisation_id));
CREATE TABLE IF NOT EXISTS aws_checks (id text PRIMARY KEY,connection_id text NOT NULL REFERENCES aws_connections(id),success boolean NOT NULL,detail jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS billing_snapshots (id text PRIMARY KEY,organisation_id text NOT NULL REFERENCES "organization"(id),connection_id text NOT NULL REFERENCES aws_connections(id),period_start date NOT NULL,period_end date NOT NULL,currency text NOT NULL,cost numeric(24,8) NOT NULL,estimated boolean NOT NULL,metric text NOT NULL,service text NOT NULL,source jsonb NOT NULL,collected_at timestamptz NOT NULL DEFAULT now(),UNIQUE(connection_id,period_start,period_end,currency,metric,service));
CREATE TABLE IF NOT EXISTS files (id text PRIMARY KEY,organisation_id text NOT NULL REFERENCES "organization"(id),engagement_id text,object_key text NOT NULL UNIQUE,filename text NOT NULL,mime text NOT NULL,size bigint NOT NULL,sha256 text NOT NULL,status text NOT NULL DEFAULT 'quarantined',provider text NOT NULL,uploaded_by text NOT NULL,scan_error text,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(engagement_id,organisation_id) REFERENCES engagements(id,organisation_id));
CREATE TABLE IF NOT EXISTS organisation_invitations (id text PRIMARY KEY,organisation_id text NOT NULL REFERENCES "organization"(id),email text NOT NULL,role text NOT NULL,token_hash text NOT NULL UNIQUE,expires_at timestamptz NOT NULL,accepted_at timestamptz,invited_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
